export class challenge_task {
    private _dataMap: Map<number, Ichallenge_taskConfig>
	//private _dataObj: {[index:number]:Ichallenge_taskConfig}
    private _dataList: Ichallenge_taskConfig[]
    private _loaded:boolean=false;
    private _buf: ByteBuf;
    constructor(_buf_: ByteBuf) {
        this._buf = _buf_;
        this._loaded = false;
    }

    private load():void{
        if(this._loaded){
            return;
        }
        let _buf_ = this._buf;
        if(!_buf_){
            console.error("_buf_ null");
            return;
        }
        this._dataMap = new Map<number, Ichallenge_taskConfig>()
        this._dataList = []
		//this._dataObj = {}
        for(let n = _buf_.ReadInt(); n > 0; n--) {
            let _v: Ichallenge_taskConfig
            _v = new Ichallenge_taskConfig(_buf_)
            this._dataList.push(_v)
            this._dataMap.set(_v.task_id, _v)
			//this._dataObj[_v.task_id] = _v
        }
        this._loaded = true;
    }
    getDataMap(): Map<number, Ichallenge_taskConfig> {this.load(); return this._dataMap; }
	
	//getDataObj(): { [index: number]: Ichallenge_taskConfig } {this.load(); return this._dataObj; }
	
    getDataList(): Ichallenge_taskConfig[] { this.load();return this._dataList; }

    get(key: number): Ichallenge_taskConfig | undefined {
		this.load();
        return this._dataMap.get(key); 
    }
    
/**
    resolve(tables:Tables) {
        
    }
 */    

}




