	//private _dataObj: {[index:number]:Iyqlj}
    private _dataList: Iyqlj[]
    private _loaded:boolean=false;
    private _buf: ByteBuf;
    constructor(_buf_: ByteBuf) {
        this._buf = _buf_;
        this._loaded = false;
    }

    private load():void{
        if(this._loaded){
            return;
        }
        let _buf_ = this._buf;
        if(!_buf_){
            console.error("_buf_ null");
            return;
        }
        this._dataMap = new Map<number, Iyqlj>()
        this._dataList = []
		//this._dataObj = {}
        for(let n = _buf_.ReadInt(); n > 0; n--) {
            let _v: Iyqlj
            _v = new Iyqlj(_buf_)
            this._dataList.push(_v)
            this._dataMap.set(_v.id, _v)
			//this._dataObj[_v.id] = _v
        }
        this._loaded = true;
    }
    getDataMap(): Map<number, Iyqlj> {this.load(); return this._dataMap; }
	
	//getDataObj(): { [index: number]: Iyqlj } {this.load(); return this._dataObj; }
	
    getDataList(): Iyqlj[] { this.load();return this._dataList; }

    get(key: number): Iyqlj | undefined {
		this.load();
        return this._dataMap.get(key); 
    }
    
